package com.gpcbellary.cms.controller; import com.gpcbellary.cms.model.Result; import com.gpcbellary.cms.repository.ResultRepository; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/results") @CrossOrigin public class ResultController{private final ResultRepository repo; public ResultController(ResultRepository repo){this.repo=repo;} @GetMapping public List<Result> all(){return repo.findAll();} @GetMapping("/year/{year}") public List<Result> byYear(@PathVariable String year){return repo.findByAcademicYearOrderByBranchAscStudentNameAsc(year);} @PostMapping public Result create(@RequestBody Result x){return repo.save(x);} @PutMapping("/{id}") public Result update(@PathVariable Long id,@RequestBody Result x){x.setId(id);return repo.save(x);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);}}
